// Feed navigation renders synthetic time buckets, not the folder tree.
import type { MouseEvent as ReactMouseEvent, RefObject } from "react";
import { useCallback } from "react";
import { useShallow } from "zustand/react/shallow";

import { useEditor } from "@/features/notes/editor/hooks/editor-context";
import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
import { type DesktopContextMenuState } from "@/app/hooks/use-tree-interactions";
import { useSelection } from "@/app/state/selection-store";
import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
import { focusNoScroll } from "@/shared/lib/dom";
import { computeRangeSelection } from "@/shared/lib/selection";
import { TreeNode } from "./tree-node";

type FeedPanelProps = {
  paneBodyRef: RefObject<HTMLDivElement | null>;
  onNavigateToNotes?: () => void;
  onPaneClick?: () => void;
  onPaneKeyDown?: (event: React.KeyboardEvent<HTMLDivElement>) => void;
  onOpenContextMenu: (state: DesktopContextMenuState) => void;
};

export function FeedPanel({
  paneBodyRef,
  onNavigateToNotes,
  onPaneClick,
  onPaneKeyDown,
  onOpenContextMenu,
}: FeedPanelProps) {
  const { clearDraft, clearNote } = useEditor();
  const {
    feedTreeData,
    feedNodeById,
    activeFeedGroup,
    setActiveFeedGroup,
    expanded,
    setExpanded,
    allNotePreviews,
    feedLoading,
    shouldNestNotesInNavigation,
  } = useNotesTree();
  const {
    selectFolder,
    selectNote,
    setSelectedFolders,
    setLastSelectedFolder,
    setActiveFolder,
    selectedNotes,
    setSelectedNotes,
    lastSelectedNote,
    setLastSelectedNote,
    setActiveNote,
  } = useSelection(
    useShallow((state) => ({
      selectFolder: state.selectFolder,
      selectNote: state.selectNote,
      setSelectedFolders: state.setSelectedFolders,
      setLastSelectedFolder: state.setLastSelectedFolder,
      setActiveFolder: state.setActiveFolder,
      selectedNotes: state.selectedNotes,
      setSelectedNotes: state.setSelectedNotes,
      lastSelectedNote: state.lastSelectedNote,
      setLastSelectedNote: state.setLastSelectedNote,
      setActiveNote: state.setActiveNote,
    }))
  );

  const selectFeedGroup = useCallback(
    (groupId: string) => {
      onNavigateToNotes?.();
      setActiveFeedGroup(groupId);
      selectFolder(FEED_FOLDER_PATH);
      clearDraft();
      clearNote();
      focusNoScroll(paneBodyRef.current);
    },
    [
      clearDraft,
      clearNote,
      onNavigateToNotes,
      paneBodyRef,
      selectFolder,
      setActiveFeedGroup,
    ]
  );

  const handleNoteSelect = useCallback(
    (notePath: string, event: ReactMouseEvent, parentPath: string) => {
      onNavigateToNotes?.();
      const parentNode = feedNodeById.get(parentPath);
      const notePaths = parentNode?.notes.map((note) => note.path) || [];
      selectNote(
        notePath,
        FEED_FOLDER_PATH,
        computeRangeSelection(event, selectedNotes, notePaths, lastSelectedNote, notePath)
      );
      setActiveFeedGroup(parentPath);
      if (shouldNestNotesInNavigation) {
        focusNoScroll(paneBodyRef.current);
      }
    },
    [
      feedNodeById,
      lastSelectedNote,
      onNavigateToNotes,
      paneBodyRef,
      selectNote,
      selectedNotes,
      setActiveFeedGroup,
      shouldNestNotesInNavigation,
    ]
  );

  const handleToggle = useCallback(
    (event: ReactMouseEvent, id: string) => {
      event.stopPropagation();
      setExpanded((prev) => {
        const next = new Set(prev);
        if (next.has(id)) {
          next.delete(id);
        } else {
          next.add(id);
        }
        return next;
      });
    },
    [setExpanded]
  );

  const handleNoteContextMenu = useCallback(
    (event: ReactMouseEvent, notePath: string, parentPath: string) => {
      event.preventDefault();
      event.stopPropagation();
      const parentNode = feedNodeById.get(parentPath);
      const notePaths = parentNode?.notes.map((note) => note.path) || [];
      const targetPaths =
        selectedNotes.size > 1 && selectedNotes.has(notePath) ? Array.from(selectedNotes) : [notePath];
      setSelectedFolders(new Set([FEED_FOLDER_PATH]));
      setLastSelectedFolder(FEED_FOLDER_PATH);
      setActiveFolder(FEED_FOLDER_PATH);
      if (!selectedNotes.has(notePath)) {
        setSelectedNotes(new Set([notePath]));
        setLastSelectedNote(notePath);
      }
      setActiveFeedGroup(parentPath);
      setActiveNote(notePath);
      focusNoScroll(paneBodyRef.current);
      onOpenContextMenu({
        kind: "note",
        x: event.clientX,
        y: event.clientY,
        path: notePath,
        parentPath,
        targetPaths: targetPaths.length > 0 ? targetPaths : notePaths,
      });
    },
    [
      feedNodeById,
      onOpenContextMenu,
      paneBodyRef,
      selectedNotes,
      setActiveFeedGroup,
      setActiveFolder,
      setActiveNote,
      setLastSelectedFolder,
      setLastSelectedNote,
      setSelectedFolders,
      setSelectedNotes,
    ]
  );

  if (feedTreeData.length === 0) {
    return (
      <div className="empty">
        {feedLoading ? "Loading feed..." : "No feed notes yet."}
      </div>
    );
  }

  return (
    <div
      className="nav-scroll-area"
      ref={paneBodyRef}
      tabIndex={0}
      onKeyDown={onPaneKeyDown}
      onClick={(event) => {
        if (onPaneClick) {
          onPaneClick();
        }
        if (event.target === event.currentTarget) {
          selectFeedGroup(activeFeedGroup || feedTreeData[0].id);
        }
      }}
    >
      <div className="pane-body tree-root feed-navigation-tree">
        {feedTreeData.map((node) => (
          <TreeNode
            key={node.id}
            node={node}
            depth={0}
            selectedIds={activeFeedGroup ? new Set([activeFeedGroup]) : new Set()}
            selectedNoteIds={selectedNotes}
            showNotesAsChildren={shouldNestNotesInNavigation}
            edgeSnap={null}
            expanded={expanded}
            feedMode
            onSelect={(event, id) => {
              event.stopPropagation();
              selectFeedGroup(id);
            }}
            onToggle={handleToggle}
            onNoteSelect={handleNoteSelect}
            onNoteContextMenu={handleNoteContextMenu}
            notePreviews={allNotePreviews}
            onContextMenu={(event, id) => {
              event.preventDefault();
              event.stopPropagation();
              selectFeedGroup(id);
            }}
            indentationWidth={18}
            draggable={false}
          />
        ))}
      </div>
    </div>
  );
}
import type { MouseEvent as ReactMouseEvent, RefObject } from "react";
import { SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";

import { NoteRow } from "@/features/notes/list/components/note-row";
import { SettingsMiddlePane } from "@/features/settings/components/desktop/settings-panel";
import type { SettingsSectionId } from "@/features/settings/lib/sections";

import { focusNoScroll } from "@/shared/lib/dom";
import type { AppMode } from "@typenotes/shared/types";

type DesktopMiddlePaneProps = {
  appMode: AppMode;
  activeSettingsSection: SettingsSectionId;
  onSettingsSectionChange: (id: SettingsSectionId) => void;
  notesPanelRef: RefObject<HTMLDivElement | null>;
  middlePaneRef: RefObject<HTMLDivElement | null>;
  lastLeftPaneFocusRef: RefObject<string>;
  notesTitle: string;
  notes: Array<{ path: string; name: string }>;
  notePreviews: Record<string, import("@typenotes/shared/format").NotePreview>;
  selectedNotes: Set<string>;
  onNotesKeyDown: (event: React.KeyboardEvent<HTMLDivElement>) => void;
  onNoteClick: (notePath: string, event: ReactMouseEvent, parentPath?: string) => void;
  onNoteContextMenu: (event: ReactMouseEvent, path: string, parentPath?: string) => void;
};

export function DesktopMiddlePane({
  appMode,
  activeSettingsSection,
  onSettingsSectionChange,
  notesPanelRef,
  middlePaneRef,
  lastLeftPaneFocusRef,
  notesTitle,
  notes,
  notePreviews,
  selectedNotes,
  onNotesKeyDown,
  onNoteClick,
  onNoteContextMenu,
}: DesktopMiddlePaneProps) {
  if (appMode === "notes") {
    return (
      <div className="pane notes-pane min-w-0">
        <div className="pane-drag-region" data-tauri-drag-region aria-hidden />
        <div
          className="pane-body focus:outline-none"
          ref={(node) => {
            notesPanelRef.current = node;
            middlePaneRef.current = node;
          }}
          tabIndex={0}
          onKeyDown={onNotesKeyDown}
          onClick={() => {
            lastLeftPaneFocusRef.current = "middle";
            focusNoScroll(middlePaneRef.current);
          }}
        >
          {notes.length === 0 && <div className="empty">No notes in {notesTitle}</div>}
          <SortableContext
            items={notes.map((n) => n.path)}
            strategy={verticalListSortingStrategy}
          >
            {notes.map((note) => (
              <NoteRow
                key={note.path}
                note={note}
                preview={notePreviews[note.path]}
                isSelected={selectedNotes.has(note.path)}
                onClick={onNoteClick}
                onContextMenu={onNoteContextMenu}
              />
            ))}
          </SortableContext>
        </div>
      </div>
    );
  }

  return (
    <SettingsMiddlePane
      activeSection={activeSettingsSection}
      onSectionChange={onSettingsSectionChange}
      middlePaneRef={middlePaneRef}
      onPaneClick={() => {
        lastLeftPaneFocusRef.current = "middle";
        focusNoScroll(middlePaneRef.current);
      }}
    />
  );
}
