import type { NoteEntry } from "@typenotes/shared/types";
import type { NotePreview } from "@typenotes/shared/format";

// Feed is not the folder tree. It is a synthetic hierarchy built from note
// timestamps so the navigation UI can browse recent work by time bucket.
//
// Shape of the tree (today = Sun 9 Aug 2026, for example):
//
//   Today                                    <- relative half
//   Yesterday
//   This week            running ISO week minus today/yesterday
//   Last week            the whole previous ISO week (Mon-Sun)
//   July                                     <- calendar half
//     Week 30 · Jul 20 - 26
//     Week 29 · Jul 13 - 19
//       Monday 13
//       ...
//   2025
//     Q4 > December > Week 52 · Dec 22 - 28 > Monday 22
//   Undated
//
// Three rules hold the whole thing together; break one and the old pathologies
// (empty buckets, "Month start" stubs, a week cut in half by a month boundary)
// come back:
//
//   1. The two halves are separated by one instant, FeedBoundaries.
//      calendarCutoffMs, so a date is in exactly one of them. The calendar
//      never covers the last two weeks, so it can't grow buckets that are
//      empty by construction.
//   2. Weeks are ISO weeks, never clipped to a month (getWeekOwnerMonths
//      decides which month a straddling week hangs under).
//   3. Every level reads newest-first (getChronologicalRank).
export type FeedTreeNodeKind =
  | "special"
  | "year"
  | "quarter"
  | "month"
  | "week"
  | "day"
  | "undated";

export type FeedTreeNode = {
  id: string;
  name: string;
  kind: FeedTreeNodeKind;
  parentId: string | null;
  rangeStartMs: number | null;
  rangeEndMs: number | null;
  children: FeedTreeNode[];
  notes: Array<NoteEntry & { timestampMs: number }>;
  noteCount: number;
  latestMs: number;
  rank: number;
};

export type FeedTreeBuildResult = {
  treeData: FeedTreeNode[];
  nodeById: Map<string, FeedTreeNode>;
};

type FeedNodeBuilder = {
  id: string;
  name: string;
  kind: FeedTreeNodeKind;
  parentId: string | null;
  rangeStartMs: number | null;
  rangeEndMs: number | null;
  children: Map<string, FeedNodeBuilder>;
  notes: Array<NoteEntry & { timestampMs: number }>;
  latestMs: number;
  rank: number;
};

// Intl is the hot path of this module: building the feed for thousands of
// notes used to spend seconds inside toLocaleDateString/localeCompare. Labels
// are deterministic per weekday/month/week, so they are cached, and one shared
// Collator replaces per-call localeCompare in the sorts.
const nameCollator = new Intl.Collator();
const compareNames = (left: string, right: string) => nameCollator.compare(left, right);

const WEEK_MS = 604_800_000;

// The feed has two halves and every note lands in exactly one of them, so no
// day is ever represented twice (see getFeedBoundaries):
//
//   relative half   Today / Yesterday / This week / Last week
//   calendar half   Month -> ISO week -> day   (Year -> Quarter -> ... if older)
//
// SPECIAL_GROUP_ORDER ranks the relative half; the calendar half is ranked by
// getChronologicalRank.
const SPECIAL_GROUP_ORDER: Record<string, number> = {
  today: 0,
  yesterday: 1,
  "this-week": 2,
  "last-week": 3,
  undated: 99_999,
};

// Every level of the feed reads newest-first, so calendar nodes are ranked by
// negated range start rather than by ascending week/day number.
const getChronologicalRank = (startMs: number) => -startMs;

const createBuilder = (
  id: string,
  name: string,
  kind: FeedTreeNodeKind,
  parentId: string | null,
  rank: number,
  rangeStartMs: number | null = null,
  rangeEndMs: number | null = null
): FeedNodeBuilder => ({
  id,
  name,
  kind,
  parentId,
  rangeStartMs,
  rangeEndMs,
  children: new Map(),
  notes: [],
  latestMs: 0,
  rank,
});

const ensureBuilder = (
  parent: FeedNodeBuilder,
  id: string,
  name: string,
  kind: FeedTreeNodeKind,
  rank: number,
  rangeStartMs: number | null = null,
  rangeEndMs: number | null = null
) => {
  const existing = parent.children.get(id);
  if (existing) {
    return existing;
  }
  const next = createBuilder(
    id,
    name,
    kind,
    parent.id,
    rank,
    rangeStartMs,
    rangeEndMs
  );
  parent.children.set(id, next);
  return next;
};

const getStartOfDayMs = (date: Date) => {
  const value = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  return value.getTime();
};

const getEndOfDayMs = (date: Date) =>
  new Date(
    date.getFullYear(),
    date.getMonth(),
    date.getDate(),
    23,
    59,
    59,
    999
  ).getTime();

type FeedDateRange = {
  rangeStartMs: number;
  rangeEndMs: number;
};

const clampRangeEnd = (rangeEndMs: number, now: Date) =>
  Math.min(rangeEndMs, now.getTime());

const getDayRange = (date: Date, now: Date): FeedDateRange => ({
  rangeStartMs: getStartOfDayMs(date),
  rangeEndMs: clampRangeEnd(getEndOfDayMs(date), now),
});

const getMonthRange = (date: Date, now: Date): FeedDateRange => ({
  rangeStartMs: new Date(date.getFullYear(), date.getMonth(), 1).getTime(),
  rangeEndMs: clampRangeEnd(
    new Date(
      date.getFullYear(),
      date.getMonth() + 1,
      0,
      23,
      59,
      59,
      999
    ).getTime(),
    now
  ),
});

const getYearRange = (date: Date, now: Date): FeedDateRange => ({
  rangeStartMs: new Date(date.getFullYear(), 0, 1).getTime(),
  rangeEndMs: clampRangeEnd(
    new Date(date.getFullYear(), 11, 31, 23, 59, 59, 999).getTime(),
    now
  ),
});

// --- ISO weeks -------------------------------------------------------------
// Feed weeks are ISO-8601 weeks: always Monday -> Sunday, never clipped at a
// month boundary. A week straddling two months stays ONE node holding all seven
// days; which month it hangs under is a policy decision — see
// getWeekOwnerMonths, the single place to change it.

const addDays = (date: Date, days: number) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);

const getIsoWeekStart = (date: Date) =>
  addDays(date, -((date.getDay() + 6) % 7));

// Week 1 of an ISO year is the week whose Thursday falls in that year (that is,
// the week holding January 4th), so the number is derived from the Thursday.
// Note this number is independent of the ownership policy below: changing which
// month a week hangs under never renumbers it.
const getIsoWeekNumber = (weekStart: Date) => {
  const thursday = addDays(weekStart, 3);
  const firstThursday = addDays(
    getIsoWeekStart(new Date(thursday.getFullYear(), 0, 4)),
    3
  );
  // Rounding absorbs the ±1h a DST switch puts between two local midnights.
  return 1 + Math.round((thursday.getTime() - firstThursday.getTime()) / WEEK_MS);
};

type MonthKey = { year: number; monthIndex: number };

const monthKeyOf = (date: Date): MonthKey => ({
  year: date.getFullYear(),
  monthIndex: date.getMonth(),
});

/**
 * Which calendar month a week hangs under. ISO weeks straddle month boundaries,
 * so this is a *policy*, not a fact.
 *
 * Current policy — the ISO rule: the week belongs to the month containing its
 * Thursday, i.e. the month owning the majority of its days. The week of
 * Jul 27 – Aug 2 2026 therefore hangs under July, and so does Jun 29 – Jul 5.
 * A consequence worth knowing: a week node's range can stick out past its
 * month node's range. Nothing depends on containment, but don't add code that
 * assumes it.
 *
 * Alternatives, both already supported by the call sites:
 *  - "the week starts in this month": `return [monthKeyOf(weekStart)];`
 *  - "show the week under both months": return both keys —
 *      `[monthKeyOf(weekStart), monthKeyOf(addDays(weekStart, 6))]`, deduped
 *    when the week sits inside one month. Each copy then collects only the days
 *    belonging to its own month, because pickWeekOwnerMonth() routes each note
 *    to the matching copy. The week shows up twice; no note is duplicated.
 *    Weeks are keyed by ISO number under their owner month, so the two copies
 *    still get distinct node ids.
 */
const getWeekOwnerMonths = (weekStart: Date): MonthKey[] => [
  monthKeyOf(addDays(weekStart, 3)),
];

/**
 * Picks the owner copy a note belongs to. Only meaningful when
 * getWeekOwnerMonths returns more than one month (the "duplicate across months"
 * policy); with a single owner it is that owner.
 */
const pickWeekOwnerMonth = (owners: MonthKey[], date: Date) =>
  owners.find(
    (owner) =>
      owner.year === date.getFullYear() && owner.monthIndex === date.getMonth()
  ) ?? owners[0];

const getWeekRange = (weekStart: Date, now: Date): FeedDateRange => ({
  rangeStartMs: weekStart.getTime(),
  rangeEndMs: clampRangeEnd(getEndOfDayMs(addDays(weekStart, 6)), now),
});

const weekLabelCache = new Map<number, string>();

const getWeekLabel = (weekStart: Date) => {
  const cacheKey = weekStart.getTime();
  const cached = weekLabelCache.get(cacheKey);
  if (cached) {
    return cached;
  }
  const weekEnd = addDays(weekStart, 6);
  const formatDay = (value: Date) =>
    value.toLocaleDateString([], { month: "short", day: "numeric" });
  const range =
    weekStart.getMonth() === weekEnd.getMonth()
      ? `${formatDay(weekStart)} - ${weekEnd.getDate()}`
      : `${formatDay(weekStart)} - ${formatDay(weekEnd)}`;
  const label = `Week ${getIsoWeekNumber(weekStart)} · ${range}`;
  weekLabelCache.set(cacheKey, label);
  return label;
};

type FeedBoundaries = {
  todayStartMs: number;
  yesterdayStartMs: number;
  thisWeekStartMs: number;
  /**
   * Start of the previous ISO week, and the seam between the feed's two halves:
   * at or after it a note goes to a relative bucket, before it to the calendar.
   * Because the seam is a single instant, the halves cannot overlap — which is
   * what keeps the calendar free of always-empty "the last few days" nodes.
   */
  calendarCutoffMs: number;
};

const getFeedBoundaries = (now: Date): FeedBoundaries => {
  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const thisWeekStart = getIsoWeekStart(todayStart);
  return {
    todayStartMs: todayStart.getTime(),
    yesterdayStartMs: addDays(todayStart, -1).getTime(),
    thisWeekStartMs: thisWeekStart.getTime(),
    calendarCutoffMs: addDays(thisWeekStart, -7).getTime(),
  };
};

// Read side of the notes navigation slice.
import { useCallback, useEffect, useMemo, useState } from "react";
import { useAppearance } from "@/app/state/appearance-store";
import { useProfiles } from "@/features/profiles/hooks/profiles-context";
import { useSecurity } from "@/features/security/hooks/security-context";
import * as api from "@/features/notes/api/notes-api";
import { useNotePreviews } from "@/features/notes/list/hooks/use-note-previews";
import type { FolderNode, NoteEntry, VisibleNavigationItem } from "@typenotes/shared/types";
import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
import { collectAllNotes, getNoteParentPath } from "@typenotes/shared/notes";
import { buildTreeItems, findNode, flattenTree } from "@/features/notes/navigation/model/tree-ops";
import { removeChildrenOf } from "@/features/notes/navigation/model/dnd-tree";
import type { NotePreview } from "@typenotes/shared/format";
import type { TreeItem } from "@/features/notes/navigation/model/types";
import type { FlattenedItem } from "@/features/notes/navigation/model/types";
import {
  buildFeedTree,
  collectFeedNotes,
  findFeedNode,
  getFirstFeedGroupId,
  type FeedTreeNode,
} from "@/features/notes/navigation/model/feed-tree-model";
import {
  buildNotePreviews,
  mapParentById,
  selectPreviewSourceNotes,
} from "@/features/notes/navigation/model/notes-tree-model";
import { buildVisibleNavigationItems } from "@/features/notes/navigation/model/visible-navigation";

type UseNotesTreeStateArgs = {
  activeFolder: string;
};

export type NotesTreeState = {
  tree: FolderNode | null;
  setTree: React.Dispatch<React.SetStateAction<FolderNode | null>>;
  treeData: TreeItem[];
  flatItems: FlattenedItem[];
  visibleItems: FlattenedItem[];
  orderedIds: string[];
  flatItemById: Map<string, FlattenedItem>;
  expanded: Set<string>;
  setExpanded: React.Dispatch<React.SetStateAction<Set<string>>>;
  notes: NoteEntry[];
  allNotes: NoteEntry[];
  notePreviews: Record<string, NotePreview>;
  allNotePreviews: Record<string, NotePreview>;
  activeNode: FolderNode | null;
  visibleNavigationItems: VisibleNavigationItem[];
  feedVisibleNavigationItems: VisibleNavigationItem[];
  feedTreeData: FeedTreeNode[];
  feedNodeById: Map<string, FeedTreeNode>;
  activeFeedGroup: string;
  setActiveFeedGroup: React.Dispatch<React.SetStateAction<string>>;
  activeFeedNode: FeedTreeNode | null;
  feedNotes: Array<NoteEntry & { timestampMs: number }>;
  feedNotePreviews: Record<string, NotePreview>;
  feedLoading: boolean;
  parentById: Record<string, string | null>;
  renamingFolder: string | null;
  setRenamingFolder: React.Dispatch<React.SetStateAction<string | null>>;
  renameValue: string;
  setRenameValue: (value: string) => void;
  refreshTree: () => Promise<void>;
  shouldNestNotesInNavigation: boolean;
};

export function useNotesTreeState({
  activeFolder,
}: UseNotesTreeStateArgs): NotesTreeState {
  const { activeProfileId, activeProfileNotesRoot } = useProfiles();
  const { isSecurityEnabled } = useSecurity();
  const notesListMode = useAppearance((state) => state.notesListMode);
  const hideArchivedFeedNotes = useAppearance((state) => state.hideArchivedFeedNotes);

  const [tree, setTree] = useState<FolderNode | null>(null);
  const [expanded, setExpanded] = useState<Set<string>>(new Set([""]));
  const [activeFeedGroup, setActiveFeedGroup] = useState("");
  const [renamingFolder, setRenamingFolder] = useState<string | null>(null);
  const [renameValue, setRenameValue] = useState("");

  const shouldNestNotesInNavigation = notesListMode === "nested";

  const refreshTree = useCallback(async () => {
    const data = await api.getTree();
    setTree(data);
  }, []);

  const treeData = useMemo(() => {
    if (!tree) return [] as TreeItem[];
    return buildTreeItems(tree);
  }, [tree]);

  const flatItems = useMemo(() => flattenTree(treeData), [treeData]);

  const visibleItems = useMemo(() => {
    const collapsedIds = flatItems
      .filter((item) => item.children.length > 0 && !expanded.has(item.id))
      .map((item) => item.id);
    return removeChildrenOf(flatItems, collapsedIds);
  }, [flatItems, expanded]);

  const orderedIds = useMemo(() => visibleItems.map((item) => item.id), [visibleItems]);
  const flatItemById = useMemo(
    () => new Map(flatItems.map((item) => [item.id, item] as const)),
    [flatItems]
  );

  const activeNode = useMemo(() => findNode(tree, activeFolder), [tree, activeFolder]);
  const notes = useMemo(() => activeNode?.notes || [], [activeNode]);
  const allNotes = useMemo(() => collectAllNotes(tree), [tree]);
  const feedSourceNotes = useMemo(
    () => allNotes.filter((note) => getNoteParentPath(note.path) === FEED_FOLDER_PATH),
    [allNotes]
  );
  const previewSourceNotes = useMemo<NoteEntry[]>(
    () =>
      selectPreviewSourceNotes({
        activeFolder,
        notes,
        feedNotes: feedSourceNotes,
        allNotes,
        shouldNestNotesInNavigation,
      }),
    [
      activeFolder,
      notes,
      feedSourceNotes,
      allNotes,
      shouldNestNotesInNavigation,
    ]
  );
  const allNotePaths = useMemo(() => allNotes.map((note) => note.path), [allNotes]);
  const {
    previews: allNotePreviews,
    isLoading: notePreviewsLoading,
  } = useNotePreviews(previewSourceNotes, {
    resetKey: activeProfileId
      ? `${activeProfileId}:${activeProfileNotesRoot ?? ""}`
      : null,
    // Plaintext preview snapshots must never persist for encrypted vaults.
    persistKey: !isSecurityEnabled && activeProfileId ? activeProfileId : null,
    allNotePaths,
  });
  const notePreviews = useMemo(
    () => buildNotePreviews(notes, allNotePreviews),
    [allNotePreviews, notes]
  );
  const feedTree = useMemo(
    () => buildFeedTree(feedSourceNotes, allNotePreviews, hideArchivedFeedNotes),
    [allNotePreviews, feedSourceNotes, hideArchivedFeedNotes]
  );
  const feedTreeData = feedTree.treeData;
  const feedNodeById = feedTree.nodeById;
  const feedVisibleNavigationItems = useMemo(
    () => buildVisibleNavigationItems(feedTreeData, expanded, shouldNestNotesInNavigation),
    [expanded, feedTreeData, shouldNestNotesInNavigation]
  );

  useEffect(() => {
    if (feedTreeData.length === 0) {
      if (activeFeedGroup) {
        setActiveFeedGroup("");
      }
      return;
    }
    if (!activeFeedGroup || !feedNodeById.has(activeFeedGroup)) {
      setActiveFeedGroup(getFirstFeedGroupId(feedTreeData));
    }
  }, [activeFeedGroup, feedNodeById, feedTreeData]);

  const activeFeedNode = useMemo(
    () => findFeedNode(feedTreeData, activeFeedGroup),
    [activeFeedGroup, feedTreeData]
  );
  const feedNotes = useMemo(() => collectFeedNotes(activeFeedNode), [activeFeedNode]);
  const feedNotePreviews = useMemo(
    () => buildNotePreviews(feedNotes, allNotePreviews),
    [allNotePreviews, feedNotes]
  );
  const feedLoading = feedSourceNotes.length > 0 && notePreviewsLoading;

  const parentById = useMemo(() => mapParentById(flatItems), [flatItems]);

  const visibleNavigationItems = useMemo(
    () => buildVisibleNavigationItems(treeData, expanded, shouldNestNotesInNavigation),
    [expanded, shouldNestNotesInNavigation, treeData]
  );

  // Tree state is profile-scoped. Any profile/root switch should throw away the
  // cached tree and rebuild it from the active root instead of trying to diff.
  useEffect(() => {
    if (!activeProfileId) {
      return;
    }
    setTree(null);
    void refreshTree();
  }, [activeProfileId, activeProfileNotesRoot, refreshTree]);

  useEffect(() => {
    const onTreeInvalidated = () => {
      void refreshTree();
    };
    window.addEventListener("notes-tree-invalidated", onTreeInvalidated);
    return () => window.removeEventListener("notes-tree-invalidated", onTreeInvalidated);
  }, [refreshTree]);

  return {
    tree,
    setTree,
    treeData,
    flatItems,
    visibleItems,
    orderedIds,
    flatItemById,
    expanded,
    setExpanded,
    notes,
    allNotes,
    notePreviews,
    allNotePreviews,
    activeNode,
    visibleNavigationItems,
    feedVisibleNavigationItems,
    feedTreeData,
    feedNodeById,
    activeFeedGroup,
    setActiveFeedGroup,
    activeFeedNode,
    feedNotes,
    feedNotePreviews,
    feedLoading,
    parentById,
    renamingFolder,
    setRenamingFolder,
    renameValue,
    setRenameValue,
    refreshTree,
    shouldNestNotesInNavigation,
  };
}
