176	  return (
177	    <div className="feed-panel-layout">
178	      <div className="feed-filter-bar">
179	        <label htmlFor="feed-note-filter">Show</label>
180	        <NativeSelect
181	          id="feed-note-filter"
182	          size="sm"
183	          value={feedNoteFilter}
184	          onChange={(event) =>
185	            setFeedNoteFilter(event.target.value as FeedNoteFilter)
186	          }
187	          aria-label="Filter Feed notes"
188	          className="feed-filter-select"
189	        >
190	          <NativeSelectOption value="all">All notes</NativeSelectOption>
191	          <NativeSelectOption value="active">Active</NativeSelectOption>
192	          <NativeSelectOption value="reviewed">Reviewed</NativeSelectOption>
193	          <NativeSelectOption value="unreviewed">Unreviewed</NativeSelectOption>
194	          <NativeSelectOption value="archived">Archived</NativeSelectOption>
195	        </NativeSelect>
196	      </div>
197	      <div
198	        className="nav-scroll-area focus:outline-none"
199	        ref={paneBodyRef}
200	        tabIndex={0}
201	        onKeyDown={onPaneKeyDown}
202	        onClick={(event) => {
203	          if (onPaneClick) {
204	            onPaneClick();
205	          }
206	          if (event.target === event.currentTarget && feedTreeData[0]) {
207	            selectFeedGroup(activeFeedGroup || feedTreeData[0].id);
208	          }
209	        }}
210	      >
211	        {feedTreeData.length === 0 ? (
212	          <div className="empty">
213	            {feedLoading
214	              ? "Loading feed..."
215	              : feedNoteFilter === "all"
216	                ? "No feed notes yet."
217	                : `No ${feedNoteFilter} notes.`}
218	          </div>
219	        ) : (
220	          <div className="pane-body tree-root feed-navigation-tree">
221	            {feedTreeData.map((node) => (
222	              <TreeNode
223	                key={node.id}
224	                node={node}
225	                depth={0}
226	                selectedIds={
227	                  activeFeedGroup ? new Set([activeFeedGroup]) : new Set()
228	                }
229	                selectedNoteIds={selectedNotes}
230	                showNotesAsChildren={shouldNestNotesInNavigation}
231	                edgeSnap={null}
232	                expanded={expanded}
233	                feedMode
234	                onSelect={(event, id) => {
235	                  event.stopPropagation();
236	                  selectFeedGroup(id);
237	                }}
238	                onToggle={handleToggle}
239	                onNoteSelect={handleNoteSelect}
240	                onNoteContextMenu={handleNoteContextMenu}
241	                notePreviews={allNotePreviews}
242	                onContextMenu={(event, id) => {
